# Produces: T001
def acc_cell_str(k, n):
    return f"{100 * k / n:.0f}% ({k}/{n})"


def msd(v):
    v = np.asarray(v, float)
    if len(v) == 0:
        return ""
    if len(v) == 1:
        return f"{v[0]:.2f}"
    return f"{v.mean():.2f} ({v.std(ddof=1):.2f})"


def pooled_row(f, j):
    k, n = int(trials.loc[trials.true_flavor == f, "correct"].sum()), \
        int((trials.true_flavor == f).sum())
    return [FLAVORS_EN[f], f"{M_pred[:, j].mean():.0f}%", acc_cell_str(k, n),
            f"{trials.loc[trials.true_flavor == f, 'certainty'].mean():.2f}",
            f"{M_alike[:, j].mean():.2f}",
            f"{trials.loc[trials.true_flavor == f, 'liking'].mean():.2f}"]


TABLE1 = [["Flavor", "predicted accuracy", "accuracy", "certainty",
           "stated liking", "tasted liking"]]
for j, f in enumerate(FLAVORS):
    TABLE1.append(pooled_row(f, j))
TABLE1.append(["All flavors", f"{np.mean([pred_mean[i] for i in range(4)]):.0f}%",
               acc_cell_str(int(trials.correct.sum()), 100),
               msd(trials["certainty"].to_numpy()),
               f"{M_alike.mean():.2f}",
               msd(trials["liking"].to_numpy())])
