# ==== A23 [analysis]: Generate Figure 2 ... ====
# Summary:
#   Generate Figure 2: relative variance components for identification accuracy, stated liking,
#   and tasted liking, splitting each into perceiver, flavor, and relationship components
#   (with the relationship noise floor shown for accuracy and tasted liking).
# Source quote:
#   "Figure 2 Variance Decomposition of Identification Accuracy, Stated Liking, and Tasted
#   Liking"
# Inputs: inputs/make_figures.py
# Depends on: A17, A19, A21
# Produces: T004
def _vc_shares(raw, floor, adj):
    vp, vt, vr = raw
    tot = vp + vt + vr
    out = {"perceiver": vp / tot, "flavor": vt / tot}
    if floor is None:
        out["relationship"] = vr / tot
        out["rel_error"] = 0.0
    else:
        out["relationship"] = adj[2] / tot
        out["rel_error"] = floor[2] / tot
    return out


