# ==== A26 [analysis]: Per-perceiver stated-tasted unique-liking correspondence ... ====
# Summary:
#   For each perceiver correlate the six stated and tasted relationship effects (exact
#   permutation p over 720 orderings) and the raw profile correlations; report the range of
#   the stated-tasted unique liking correspondence.
# Source quote:
#   "Ella, the best differentiator and well calibrated about it, also shows the strongest
#   stated-tasted correspondence (raw profile r = .93, exact p = .0056 ...)."
# Inputs: inputs/gummibear_trials.csv, inputs/gummibear_apriori_long.csv
# Depends on: A03, L01, L03
# Produces: T119, T120, T121, T122, T123, T124, T125, T126, T127, T128, T129, T130, T131, T132, T133
_perms6 = list(itertools.permutations(range(6)))
_R_REL, _R_RAW = {}, {}
for _i, _p in enumerate(PERSONS):
    _r_rel = pearson(REL_A[_i], REL_T[_i])
    _r_raw = pearson(M_alike[_i], M_tlike[_i])
    _c_rel = _c_raw = 0
    for _perm in _perms6:
        _Ap = M_alike.copy()
        _Ap[_i] = M_alike[_i, list(_perm)]
        _ra = dc(_Ap)
        if abs(pearson(_ra[_i], REL_T[_i])) >= abs(_r_rel) - 1e-12:
            _c_rel += 1
        if abs(pearson(_Ap[_i], M_tlike[_i])) >= abs(_r_raw) - 1e-12:
            _c_raw += 1
    _R_REL[_p] = (_r_rel, _c_rel / 720)
    _R_RAW[_p] = (_r_raw, _c_raw / 720)
T119, T120 = _R_REL["Ada"]       # 0.459 / 0.6917
T121, T122 = _R_REL["Ella"]      # 0.613 / 0.2500
T123, T124 = _R_REL["Natalie"]   # 0.255 / 0.6667
T125, T126 = _R_REL["Mitja"]     # 0.132 / 0.8528
T127, T128 = _R_RAW["Ella"]      # 0.929 / 0.0056
T129, _ = _R_RAW["Mitja"]        # 0.519
T130, _ = _R_RAW["Ada"]          # -0.552
T131, _ = _R_RAW["Natalie"]      # -0.426
T132 = min(_R_REL[p][0] for p in PERSONS)   # 0.132 -> .13
T133 = max(_R_REL[p][0] for p in PERSONS)   # 0.613 -> .61
